import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"应届生和新手如何提升竞争力","description":"","frontmatter":{},"headers":[],"relativePath":"books/career-guide/08-职业规划-3.1-通过职业画布理解应届生和新手的市场竞争力.md","filePath":"books/career-guide/08-职业规划-3.1-通过职业画布理解应届生和新手的市场竞争力.md","lastUpdated":1781445373000}'),p={name:"books/career-guide/08-职业规划-3.1-通过职业画布理解应届生和新手的市场竞争力.md"};function l(i,a,h,d,n,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="应届生和新手如何提升竞争力" tabindex="-1">应届生和新手如何提升竞争力 <a class="header-anchor" href="#应届生和新手如何提升竞争力" aria-label="Permalink to &quot;应届生和新手如何提升竞争力&quot;">​</a></h1><p>我们接下来讲一下应届生和新手如何提升职业竞争力。因为应届生和新手，没有经验或者经验比较少，所以在求职的时候难度相对来说比较大。一旦你熟悉了这个方法，在后边就会走得比较顺了。</p><h2 id="职业画布" tabindex="-1">职业画布 <a class="header-anchor" href="#职业画布" aria-label="Permalink to &quot;职业画布&quot;">​</a></h2><p>在这里会用到我们前边提到的第三个工具——「职业画布」。「职业画布」其实是从「商业模式画布」演变过来的，虽然作用的行业不同，但它们其实都是关于价值的规划工具，只不过一个是商业价值，一个是职业价值。</p><p><img src="https://user-gold-cdn.xitu.io/2017/11/2/a32ea613f8a2854f3c5c96fa773df468" alt="" loading="lazy"></p><h3 id="设计价值主张" tabindex="-1">设计价值主张 <a class="header-anchor" href="#设计价值主张" aria-label="Permalink to &quot;设计价值主张&quot;">​</a></h3><p>在画布被分成了九个格子。最中间的格子，就是我们的价值主张。这个格子不是独立的，它其实是和最右边的格子联动的。其实就是说，「我们能给什么样的公司，贡献什么样的价值」。同样能力的人，对于不同的公司的价值不同，这个之前我们已经强调过了。</p><h3 id="构建价值" tabindex="-1">构建价值 <a class="header-anchor" href="#构建价值" aria-label="Permalink to &quot;构建价值&quot;">​</a></h3><p>左边的格子，是关于如何构建价值的，我们把价值主张定义好了，那我们要按照这个定义来构建价值。</p><p>首先是清晰的自我分析，我是谁、我具备哪些资源和技能、相对于其他求职者，我的竞争优势是什么；然后是在我们所做的价值主张中，哪些能力是我薄弱的或者暂时还不具备的，通过什么样的手段可以获得或增强，具体的措施和时间表是什么；最左边，是外部资源和优势，属于加分项，有最好，没有也无所谓。</p><h3 id="传递价值主张" tabindex="-1">传递价值主张 <a class="header-anchor" href="#传递价值主张" aria-label="Permalink to &quot;传递价值主张&quot;">​</a></h3><p>右边的格子，是关于如何传递和证明价值主张的。我们规划好了价值主张，又及时的补齐了对应的能力，但酒好也怕巷子深，这样是不够的。首先要考虑「如何让雇主知道你」，也就是求职渠道问题，这个前边我们有过讨论；然后是「如何让雇主相信你」，是说我们还要尽可能的提供可信的证据来证明我们的价值主张是正确的，一般是在简历中和面试提供「经历证明」和「能力证明」来达到目的的。关于简历在下一章会详细讲，这里先略过。</p><h2 id="应届生求职实践" tabindex="-1">应届生求职实践 <a class="header-anchor" href="#应届生求职实践" aria-label="Permalink to &quot;应届生求职实践&quot;">​</a></h2><p>这里我们以一个虚拟的大学生——薛小生同学为例子，来进行一个完整的求职实践。</p><h3 id="薛小生的基本情况" tabindex="-1">薛小生的基本情况 <a class="header-anchor" href="#薛小生的基本情况" aria-label="Permalink to &quot;薛小生的基本情况&quot;">​</a></h3><p><img src="https://user-gold-cdn.xitu.io/2017/11/2/07ee2fa33cb12aab10bbf5d180766235" alt="" loading="lazy"></p><p>从上边的图可以看到，薛小生同学是一个非重点大学（学校虚构的）的计算机系学生，现在大三。</p><p>为什么应届生的求职实践我们找了一个大三的同学呢？因为「构建价值」需要时间。尤其是应届生，绝大部分都不具备和其他同学不一样的价值，所以越早进行职业规划、越容易和同学们拉开差距，在校招中，你只需要「跑赢同学」。</p><p>薛小生同学有一点不算突出的爱好，就是喜欢拍照，所以会用 PS 修图，在科技社缺人的情况下，他帮着做过网页，懂一点 HTML 。</p><p>大体来讲，这就是一个稍微懂点技术的计算机系学生的样本。</p><h3 id="薛小生的求职意向" tabindex="-1">薛小生的求职意向 <a class="header-anchor" href="#薛小生的求职意向" aria-label="Permalink to &quot;薛小生的求职意向&quot;">​</a></h3><p><img src="https://user-gold-cdn.xitu.io/2017/11/2/51f885c2f83f1f866c2b73f43f60b7ad" alt="" loading="lazy"></p><p>去什么样的公司，似乎是一个傻问题。当然是去能的最好最有名薪资最多还不加班的公司了对吧。但越好的公司，对求职者的要求就越高，竞争就越激烈，需要为其准备的时间就越长、难度就越大。</p><p>而从薛小生同学的个人情况看，并不属于 90 分以上人群；从剩余时间来看，他大概还有三个月到六个月的时间来构建自己的竞争优势（也就是职业价值）。</p><p>如何合理的利用这段时间，成为了求职的关键。</p><h3 id="适用于薛小生的求职策略" tabindex="-1">适用于薛小生的求职策略 <a class="header-anchor" href="#适用于薛小生的求职策略" aria-label="Permalink to &quot;适用于薛小生的求职策略&quot;">​</a></h3><p>如前所述，薛小生同学在最优秀公司的竞争中，很可能会失败；所以应该重点保证他在次一级公司中的竞争力。这里我们借鉴高考志愿的方式，将他想去的公司划分为三等，第一志愿、第二志愿、第三志愿；每一级志愿可以有好几家公司。</p><p>在公司的选择上，我们要尽量保证各个级别的公司的要求逐级追加的，只要每个公司都选择同样的岗位，这点基本上能保证。</p><p>然后就是岗位的选择。考虑到薛小生同学做过网页，而且有具备较好的美感，离他最近就是前端岗了。</p><p>通过之前在「需求的量化分析」一节中描述的方法，我们可以对招聘方的需求关键字进行分析。同时，我们还可以将公司按上述第一到第三志愿分级后分别分析需求关键字，然后结合分级来考虑学习或者强化的顺序和精力。</p><p>通过这样的分析，我们大体得出了一个技能补全的顺序。</p><p><img src="https://user-gold-cdn.xitu.io/2017/11/2/5e4703c4e776da1db7b30a52ce966f97" alt="" loading="lazy"></p><p>首先，补全已经接触过的 HTML 和 CSS ，因为已经实际用过，所以学习成本应该不高。这里需要特别注意的是，将「响应式设计」和「移动浏览器的优化」也纳入到学习中来，等这一部分内容学完时，薛小生同学就可以改网站的移动版和嵌入微博微信的 H5 页面。这样，我们就构成了一个基本但相对完整的价值主张。</p><p>接着，是学习 JavaScript 。从之前的量化分析可以看到，绝大部分公司都要求 HTML 、CSS 和 JavaScript 三大块技能。这部分内容较多，学习时间会比较长，要学会分成一个个小目标，不断获取成就感。每学到一部分内容，就可以加到原来做的 HTML 和 CSS 的页面上去，使其动起来。</p><p>在 JavaScript 基本学习完成后，我们应该算是完成了一个大的独立价值 —— 能独立开发一些基础的前端功能。应该回过头来强化这三部分技巧，同时选择一个常用框架，去实际的写一些例子。从之前的分析数据看，jQuery + Vue 是一个不错的组合。对框架的学习应该先理解基本原理，然后不断的在实际业务中发现问题和解决问题。如果以你想入职的公司的产品为目标去写 DEMO ，在将来面试中会很有优势。</p><p>框架层使用熟练后，就基本达到进入一般创业公司的水平了。如果这时候还有时间，为了在一流公司的求职者中脱颖而出，可以学习下如何使用 NodeJS 写后端，这部分作为加分项，通晓流程，能做基本的开发即可。</p><p>另一方面，如果薛小生同学一直跨不过框架层这一关（可能性不小，因为即使 Vue 这种号称易学的框架，也已经是 Vue + VueX + Vue-Router 这样的全家桶了），或者自觉没有竞争力，那么可以考虑学习下 PHP 作为加分项，毕竟五分之一的公司都提到了。</p><h3 id="薛小生的职业画布" tabindex="-1">薛小生的职业画布 <a class="header-anchor" href="#薛小生的职业画布" aria-label="Permalink to &quot;薛小生的职业画布&quot;">​</a></h3><p>然后我们来填写薛小生的职业画布。其中黄色的是第一志愿，表示最好的情况；红色的是第三志愿（假设只分了三级），表示最差的情况。紫色部分表示各级志愿公用。</p><p><img src="https://user-gold-cdn.xitu.io/2017/11/2/b4f2c8ff8f589070414c2b165da95fc4" alt="" loading="lazy"></p><p>我们先讲紫色部分。</p><h4 id="认清自己" tabindex="-1">认清自己 <a class="header-anchor" href="#认清自己" aria-label="Permalink to &quot;认清自己&quot;">​</a></h4><p>首先是「我是谁」。薛小生同学要认识到自己一个二本大学的计算机系学生，这意味着他在学历上不占优势；然后他熟悉网页制作、有较好的美感，有基本的 C 语言编程能力，所以学习其他的编程语言问题应该不大。</p><h4 id="怎么让雇主知道你" tabindex="-1">怎么让雇主知道你 <a class="header-anchor" href="#怎么让雇主知道你" aria-label="Permalink to &quot;怎么让雇主知道你&quot;">​</a></h4><p>最靠谱的是在该公司的学长帮你内推，然后是官网投递和校园招聘会。另外就是如果该公司有其他岗位的实习，你能胜任，但是可能没啥发展，比如最后不能转正之类的，你可以先去实习，然后将来再想办法转岗。因为在实习的时候，你的能力会逐渐表现出来，如果被认可的话，内部转岗的门槛是很低的。</p><h4 id="怎么让雇主相信你" tabindex="-1">怎么让雇主相信你 <a class="header-anchor" href="#怎么让雇主相信你" aria-label="Permalink to &quot;怎么让雇主相信你&quot;">​</a></h4><p>对于应届生来讲，经历证明主要就是实习经历了；不过对程序员来讲，还有你参与或者主导的一些开源项目也可以算进来。</p><p>然后是你的个人品牌，比如你写的技术分析文章之类、你在技术社区做的分享和演讲之类的。</p><p>最后就是大公司技术部门一般有自己的微博和博客，你可以经常去互动，给他们一些反馈，讨论一些技术细节，这也会增强对你的信任感。不过切记不懂装懂。</p><h4 id="第一志愿-黄色部分" tabindex="-1">第一志愿（黄色部分） <a class="header-anchor" href="#第一志愿-黄色部分" aria-label="Permalink to &quot;第一志愿（黄色部分）&quot;">​</a></h4><h5 id="价值主张" tabindex="-1">价值主张 <a class="header-anchor" href="#价值主张" aria-label="Permalink to &quot;价值主张&quot;">​</a></h5><p>这是一个对知名上市互联网公司提出的价值主张。</p><blockquote><p>有专业的计算机知识，然后能熟练地使用 Vue 框架，同时对于刚开始流行的 PWA 有深入的研究。</p></blockquote><p>这些描述背后在说，「我基础扎实、能胜任日常开发；愿意学习，对新技术有专研精神」。这些都是大公司比较看重的。</p><h5 id="我缺少的能力" tabindex="-1">我缺少的能力 <a class="header-anchor" href="#我缺少的能力" aria-label="Permalink to &quot;我缺少的能力&quot;">​</a></h5><p>薛小生同学现在的基础并没有所说的那么扎实，所以需要安排时间，将计算机专业的那些基础课程从头到尾再过一遍，然后针对将来的面试去做相应的一些准备，比如算法和网络基础这种互联网公司经常面的东西。</p><p>「旺盛的兴趣」可以试着培养下，如果培养不出来，那就当你是在对钱感兴趣吧。</p><p>「对细节的深究」这个相对简单，主要是要学会分析问题和解决问题的方法。具体来说就是「读源码」、「跟踪分析」、「修复BUG」和「调整解决方案」的能力。</p><p>这里的这些能力要求，不是绝对的，不用和行业里边的高手去比，只要和跟你一起毕业的同学们比就好了，所以难度其实未必像看起来那么大，多花些时间，就会有收获。</p><h5 id="我要加入这家公司付出什么" tabindex="-1">我要加入这家公司付出什么 <a class="header-anchor" href="#我要加入这家公司付出什么" aria-label="Permalink to &quot;我要加入这家公司付出什么&quot;">​</a></h5><blockquote><p>三个月到六个月的认真学习，三个以上的实际项目的实践，一个以上的关键细节的精通。</p></blockquote><p>这里还包含了「即使你都做到了，还是可能进不去」的风险。</p><h5 id="我加入了这家公司能得到什么" tabindex="-1">我加入了这家公司能得到什么 <a class="header-anchor" href="#我加入了这家公司能得到什么" aria-label="Permalink to &quot;我加入了这家公司能得到什么&quot;">​</a></h5><blockquote><p>良好的培训、有竞争力的薪资、强大的职业背景、巨大的发展空间。</p></blockquote><p>毕竟是国内顶级的互联网公司嘛。</p><h4 id="第三志愿-红色部分" tabindex="-1">第三志愿（红色部分） <a class="header-anchor" href="#第三志愿-红色部分" aria-label="Permalink to &quot;第三志愿（红色部分）&quot;">​</a></h4><p>然后我们来看最坏的情况。</p><h5 id="价值主张-1" tabindex="-1">价值主张 <a class="header-anchor" href="#价值主张-1" aria-label="Permalink to &quot;价值主张&quot;">​</a></h5><blockquote><p>熟练使用 jQuery，会做移动网页适配和 H5 ，了解 PHP 和 PS。</p></blockquote><p>这个价值主张背后的意思是，我过来就能干活，不但能做前端，后端还能帮点忙，学习一段时间就能独当一面。</p><h5 id="我缺少的能力-1" tabindex="-1">我缺少的能力 <a class="header-anchor" href="#我缺少的能力-1" aria-label="Permalink to &quot;我缺少的能力&quot;">​</a></h5><p>从薛小生同学的情况来看，他虽然有一些基础，但还没能形成独立的价值。需要再强化一下做网页的能力，同时将 PHP 等后端能力作为备用和加分项。</p><h5 id="我要加入这家公司付出什么-1" tabindex="-1">我要加入这家公司付出什么 <a class="header-anchor" href="#我要加入这家公司付出什么-1" aria-label="Permalink to &quot;我要加入这家公司付出什么&quot;">​</a></h5><p>相对来说，要比之前容易多了。网页薛小生同学本来就做过，只需强化下。PHP 只要简单了解，能架设基本就能及格。</p><h5 id="我加入了这家公司能得到什么-1" tabindex="-1">我加入了这家公司能得到什么 <a class="header-anchor" href="#我加入了这家公司能得到什么-1" aria-label="Permalink to &quot;我加入了这家公司能得到什么&quot;">​</a></h5><p>首先是，有工作肯定比没工作好对吧，至少你有一个基本的薪资，不用整天处于没钱吃饭的恐惧中。</p><p>然后你可以留在互联网这个行业里，虽然当前的状况不是那么好，但埋好了火种，等到能力提升了，就有机会去更好的公司。</p><p>最后吧，它给了你一个用于学习的真实环境，那些教程都是纸上得来的，和跑着业务的系统还是不一样，各种在真实世界中才能遇到的场景，会帮你一点点累积经验。万一运气好的话，还有人手把手教。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>OK，我们大致梳理了职业画布，每一部分都还可以做进一步的深化，比如「我缺少的能力」的「补全策略」的深化我们就在「薛小生的画布」前一节详细讨论过了。</p><p>「职业画布」本身没有好坏，它只给你提供一个围绕职业价值的多维度思考方式，多花些时间去想它，会帮你更全面的解构问题。</p><p>「职业画布」也是动态的，最初填写的时候很粗糙，当你开始实践以后，就会获知更多的细节，也会发现之前的错误，这时候要回来充实它修正它，把它一直维持在最新，让你的职业竞争力一目了然。</p>',82)])])}const b=e(p,[["render",l]]);export{u as __pageData,b as default};
